<script lang="ts">import {onMount} from 'svelte';import {api} from '../lib/api.js';import type {WorkbenchState} from '../lib/workbench-state.js';export let state:WorkbenchState;let selection:any;let running=false;let result:any;let args='[]';onMount(()=>state.subscribe(value=>{selection=value.selection;result=undefined}));async function run(){if(!selection?.id||running)return;running=true;try{result=await api<any>('/api/run',{method:'POST',body:JSON.stringify({symbolId:selection.id,args:JSON.parse(args),consent:true})})}catch(error){result={error:(error as Error).message}}finally{running=false}}</script>
<section class="panel details-panel"><header><strong>Inspector</strong>{#if selection?.type==='function'}<button onclick={run} disabled={running} title="Run this function in the Atlas sandbox">{running?'Running…':'Run function'}</button>{/if}</header>{#if selection}<div class="detail-title">{selection.label??selection.name??selection.id}</div>{#if selection?.type==='function'}<label class="args-field">Arguments (JSON)<input bind:value={args} aria-label="Function arguments"/></label>{/if}{#if result}<pre class="operation-result">{JSON.stringify(result,null,2)}</pre>{/if}<dl>{#each Object.entries(selection) as [key,value]}<dt>{key}</dt><dd>{typeof value==='object'?JSON.stringify(value):String(value)}</dd>{/each}</dl>{:else}<div class="empty-copy">Select a graph node, file, process, or function to inspect its evidence.</div>{/if}</section>
